mapper.select:
SELECT audit_log_no,
       actor,
       action,
       target_type,
       target_id,
       detail::text AS detail,
       ip,
       frst_reg_dt
FROM tb_audit_log


        actor = #{actor}


        AND action = #{action}


        AND target_type = #{targetType}


        AND frst_reg_dt >= #{from}


        AND frst_reg_dt <= #{to}


ORDER BY frst_reg_dt DESC, audit_log_no DESC
LIMIT #{limit}

SELECT FROM tb_notice
use_yn = 'Y''N'
ORDER BY lst_chg_dt DESC, notice_no DESC LIMIT #{limit}

SELECT 
FROM tb_notification_event


        status = #{status}


        AND reviewed = #{reviewed}


ORDER BY frst_reg_dt DESC, notification_event_no DESC
LIMIT #{limit}

SELECT 
FROM tb_notification_event
WHERE reviewed = FALSE
  AND status = 'RETRY'
  AND next_retry_at IS NOT NULL
  AND next_retry_at <= #{now}
  AND attempt_count < #{maxAttempts}
ORDER BY next_retry_at ASC, notification_event_no ASC
LIMIT #{limit}

SELECT 
FROM tb_notification_event
WHERE event_type = #{eventType}
  AND source_type = #{sourceType}
  AND source_id = #{sourceId}
  AND reviewed = FALSE
  AND status IN ('PENDING', 'RETRY', 'FAILED')
ORDER BY notification_event_no DESC
LIMIT 1

